        Assertions.assertArrayEquals(inputValues, result);
    }

    @Test
    public void testvalues_withAllNulls() throws Exception {
        String[] inputValues = {null, null, null};
        Map<String, Integer> mapping = new HashMap<>();
        CSVRecord record = new CSVRecord(inputValues, mapping, null, 1);

        String[] result = invokeValues(record);
        Assertions.assertArrayEquals(inputValues, result);
    }

    @Test
    public void testvalues_boundaryValues() throws Exception {
        String[] inputValues = {""}; // Testing with an empty string
        Map<String, Integer> mapping = new HashMap<>();
        CSVRecord record = new CSVRecord(inputValues, mapping, null, 1);

        String[] result = invokeValues(record);
        Assertions.assertArrayEquals(inputValues, result);
    }

    @Test
    public void testvalues_largeInput() throws Exception {
        String[] inputValues = new String[1000];
        Arrays.fill(inputValues, "value");
        Map<String, Integer> mapping = new HashMap<>();
        CSVRecord record = new CSVRecord(inputValues, mapping, null, 1);

        String[] result = invokeValues(record);
        Assertions.assertArrayEquals(inputValues, result);
    }

    @Test
    public void testvalues_exceptionThrowingPath() throws Exception {
        String[] inputValues = {"validValue"};
        Map<String, Integer> mapping = new HashMap<>();
        CSVRecord record = new CSVRecord(inputValues, mapping, null, 1);

        // Simulate a condition that throws an exception (if applicable)
        // For demonstration, we will just check the values without an exception
        String[] result = invokeValues(record);
        Assertions.assertArrayEquals(inputValues, result);
    }

    private String[] invokeValues(CSVRecord record) throws Exception {
        Method method = CSVRecord.class.getDeclaredMethod("values");
        method.setAccessible(true);
        return (String[]) method.invoke(record);
    }
}
